.bubble-them-custom.mid, .msg-plain-them.plain-mid { border-radius: 4px 15px 15px 15px !important; }
.bubble-them-custom.last, .msg-plain-them.plain-last { border-radius: 4px 15px 15px 15px !important; }

/* === 我方气泡（用户） === */
.bubble-me-custom,
.bubble-me-custom.first,
.bubble-me-custom.mid,
.bubble-me-custom.last {
  background: rgba(176,176,176,0.25) !important;
  border: none !important;
  box-shadow: none !important;
  border-image: none !important;
  color: #ffffff !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1.5 !important;
  padding: 8px 12px 8px 12px !important;
  min-width: 40px !important;
  max-width: 280px !important;
  width: max-content !important;
  -webkit-backdrop-filter: blur(16px) saturate(180%) !important;
  backdrop-filter: blur(16px) saturate(180%) !important;
}

/* 我方连发分化圆角（instagram） */
.bubble-me-custom.single, .msg-plain-me.plain-single { border-radius: 15px 4px 15px 15px !important; }
.bubble-me-custom.first, .msg-plain-me.plain-first { border-radius: 15px 4px 15px 15px !important; }
.bubble-me-custom.mid, .msg-plain-me.plain-mid { border-radius: 15px 4px 15px 15px !important; }
.bubble-me-custom.last, .msg-plain-me.plain-last { border-radius: 15px 4px 15px 15px !important; }

/* 气泡间距（上下连发，兜底） */
.msg-bubble-container {
  margin-top: -2px !important;
}

/* ====== 特殊消息去气泡外壳 ======
   图片 / 表情包 / 位置 / 转账 / 礼物 / 转发卡片 等媒体消息
   （.no-padding = 所有媒体，.msg-radius-media = 视觉媒体）
   不被自订气泡的背景/描边/圆角/内边距包住，只让纯文字用气泡样式。 */
.bubble-me-custom.no-padding,
.bubble-them-custom.no-padding,
.bubble-me-custom.msg-radius-media,
.bubble-them-custom.msg-radius-media {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  border-image: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  text-shadow: none !important;
  min-width: 0 !important;
  transform: none !important;
}
/* 这些媒体气泡上的装饰贴纸伪元素也一并隐藏，避免飘在图片角上 */
.bubble-me-custom.no-padding::before, .bubble-me-custom.no-padding::after,
.bubble-them-custom.no-padding::before, .bubble-them-custom.no-padding::after,
.bubble-me-custom.msg-radius-media::before, .bubble-me-custom.msg-radius-media::after,
.bubble-them-custom.msg-radius-media::before, .bubble-them-custom.msg-radius-media::after {
  display: none !important;
}

/* ================================================
   思维链胶囊纯文案定制
   ================================================ */

