/* ================================================
   纯文字翻译（防遮挡置顶版）
   ================================================ */

:root {
  --translation-always-show: 1;
}

/* 隐藏气泡内部默认翻译组件 */
.msg-translation-wrapper {
  display: none !important;
}

/* 启用并向上贴紧，同时提升层级防遮挡 */
.msg-translation-detached {
  display: block !important;
  position: relative !important;       /* 开启相对定位 */
  z-index: 10 !important;              /* 提高层级，浮在原气泡上方 */
  margin-top: -10px !important;         /* 往上贴紧距离，按需调大或调小数值 */
  width: fit-content !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
}

/* 翻译文字：纯字无底 */
.msg-translation-detached-content {
  background: transparent !important;
  color: #ffffff !important;          /* 文字颜色 */
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  font-size: 13.5px !important;
  line-height: 1.3 !important;
  word-break: break-word !important;
}

/* 对齐方向 */
.msg-translation-detached-them {
  align-self: flex-start !important;
  left: 12px !important; /* 仅对方翻译往右移 */
}

/* ================================================
   独立引用条：毛玻璃唱片主题（大唱片 + 隐藏名字）
   ================================================ */

/* 1. 隐藏气泡内原引用，启用独立引用条 */
.msg-reply-block {
  display: none !important;
}

.msg-reply-block-detached {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  width: fit-content !important;
  max-width: 85% !important;
  margin-top: 4px !important;
  padding: 6px 12px !important;
  border-radius: 14px !important;

  /* 毛玻璃半透明效果 */
  background: rgba(255, 255, 255, 0.25) !important;
  backdrop-filter: blur(16px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(16px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08) !important;
}

/* 2. 隐藏引用的人名 */
.msg-reply-detached-name {
  display: none !important;
}

/* 3. 引用内容前面的唱片图标（放大至 24px） */
.msg-reply-block-detached::before {
  content: "" !important;
  display: inline-block !important;
  width: 24px !important;
  height: 24px !important;
  flex-shrink: 0 !important;
  background: url('https://nos.netease.com/ysf/02562b4f3bd30f83184f12003263e06a.png') no-repeat center / contain !important;
}

/* 4. 引用文字内容：超过 10 个字截断并显示省略号 */
.msg-reply-detached-text {
  max-width: 10em !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  display: inline-block !important;
}
/* === 红包卡片定制 === */
:root {
  /* 红包底图（未拆封 / 已拆封） */
  --redpacket-bg: url('https://nos.netease.com/ysf/374c7ec8e1959c446f936c5717ea2ae3.png') center/cover no-repeat;
  --redpacket-opened-bg: url('https://nos.netease.com/ysf/374c7ec8e1959c446f936c5717ea2ae3.png') center/cover no-repeat;

  /* 文字颜色统一为灰色 */
  --redpacket-color: #888888;
