}

/* 兜底保障：强制背景图生效 */
.msg-redpacket-card {
  background: url('https://nos.netease.com/ysf/374c7ec8e1959c446f936c5717ea2ae3.png') center/cover no-repeat !important;
}

/* 隐藏 🧧 表情图示 */
.msg-redpacket-emoji {
