}

/* === 去掉红包外层气泡的边缘底色与内边距 === */
.msg-bubble-container:has(.msg-redpacket-card),
.bubble-me-custom:has(.msg-redpacket-card),
.bubble-them-custom:has(.msg-redpacket-card) {
