  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}

/* 确保红包自身无多余描边与阴影 */
.msg-redpacket-card {
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
}

/* ---------------- 2. 转账卡片 ---------------- */
.msg-transfer-card:not(.msg-redpacket-card) {
  background-image: url('https://nos.netease.com/ysf/55219675ef892ecebf7085ecac300502.png') !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-color: transparent !important;
  border-radius: 24px !important;
  overflow: hidden !important;
}

/* 去掉转账的双箭头图标 */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-icon {
  display: none !important;
}

/* 去掉右上角的“转账”两个字 */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-label {
  display: none !important;
}

/* 动态替换：“转账给（对方名字）” -> “耳机 分（对方名字）一半” */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-subtitle {
