  font-size: 14px !important;
  line-height: 1.4 !important;
  color: #ffffff !important;
  display: inline-block;
}

/* 对方转给我时：显示我的名字 */
.msg-them .msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-subtitle::after {
  content: "耳机分" var(--user-name) "一半" !important;
