/* ====================================================
   网易云音乐卡片式语音（毛玻璃紧凑款）
   ==================================================== */

/* 1. 外层气泡去底色，由卡片完全接管 */
.bubble-me-custom:has(.voice-msg),
.bubble-them-custom:has(.voice-msg) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* 2. 卡片主体容器：毛玻璃半透明紧凑版 */
.voice-msg {
  background: rgba(255, 255, 255, 0.2) !important;
  backdrop-filter: blur(16px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(16px) saturate(180%) !important;
  border-radius: 14px !important;
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.4) !important;
  padding: 12px 12px 10px 12px !important;
  width: 220px !important;
  box-sizing: border-box !important;
  position: relative !important;
  overflow: hidden !important;
}

/* 3. 隐藏默认原生波形与下载键 */
.voice-waveform,
.voice-download-btn {
  display: none !important;
}

/* 4. 上半部网格布局：左侧文字，右侧专辑封面 */
.voice-controls-row {
  display: grid !important;
  grid-template-columns: 1fr 46px !important;
  grid-template-rows: auto auto !important;
  align-items: center !important;
  gap: 2px 8px !important;
  position: relative !important;
}

/* 5. 歌名（左上角） */
.voice-controls-row::before {
  grid-column: 1 / 2;
  grid-row: 1 / 2;
  content: "My Love Mine All Mine";
  font-size: 13.5px;
  font-weight: 600;
  color: #ffffff;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 6. 转文字按钮：透明覆盖在歌名位置，视觉隐藏但保留点击 */
.voice-transcription-toggle {
  position: absolute !important;
  left: 0 !important;
  top: 0 !important;
  width: 150px !important;
  height: 22px !important;
  opacity: 0 !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  z-index: 5 !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 7. 转写展开后的文字区域（点歌名展开后显示） */
.voice-transcription {
  margin-top: 8px !important;
  padding: 6px 8px !important;
  background: rgba(0, 0, 0, 0.2) !important;
  border-radius: 6px !important;
  font-size: 12px !important;
  color: rgba(255, 255, 255, 0.85) !important;
  line-height: 1.4 !important;
}

/* 8. 歌手名（左下角） */
.voice-duration {
  grid-column: 1 / 2;
  grid-row: 2 / 3;
  font-size: 0 !important;
  margin: 0 !important;
}
.voice-duration::before {
  content: "Mitski";
  font-size: 11.5px;
  color: rgba(255, 255, 255, 0.55);
  font-weight: 400;
}

/* 9. 专辑封面图与播放按钮合一（点击封面即可播放） */
.voice-play-btn {
  grid-column: 2 / 3;
  grid-row: 1 / 3;
  width: 46px !important;
  height: 46px !important;
  border-radius: 6px !important;
  background-image: url('https://nos.netease.com/ysf/6bc55146ffaee0a607652b382ceb8e68.png') !important;
  background-size: cover !important;
  background-position: center !important;
  border: none !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15) !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  padding: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* 10. 隐藏播放按钮原生 SVG 图标（封面自带按钮） */
.voice-play-btn svg {
  display: none !important;
}

/* 11. 底部细分割线与网易云音乐标识 */
.voice-msg::after {
  content: "网易云音乐" !important;
  display: flex !important;
  align-items: center !important;
  margin-top: 8px !important;
  padding-top: 8px !important;
  border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
  font-size: 10.5px !important;
  color: rgba(255, 255, 255, 0.5) !important;
  line-height: 1 !important;
  background-image: url('https://nos.netease.com/ysf/330708166ec4e2ab2c855c2803578331.png') !important;
  background-repeat: no-repeat !important;
  background-position: left center !important;
  background-size: 13px 13px !important;
  padding-left: 17px !important;
}

/* 对方图片：去掉气泡 【不用改，样式容器隐藏用】 */
.msg-them:has(.msg-image-wrapper) .msg-bubble-container,
.msg-them:has(.msg-image-wrapper) .bubble-them-custom {
   background: transparent !important;
   border: none !important;
   box-shadow: none !important;
   padding: 0 !important;
}

/* ==========【修改图片最大尺寸、圆角 在这里！】========== */
