/* ================================================
   增强补丁：当引用内容为图片/表情包时，剥离气泡与唱片
   ================================================ */

/* 1. 无论是 img 标签还是媒体类，只要检测到图片就剥离毛玻璃与背景边框 */
.msg-reply-block-detached:has(img),
.msg-reply-block-detached:has(picture),
.msg-reply-block-detached:has(.msg-reply-detached-media),
.msg-reply-block-detached:has([class*="image"]),
.msg-reply-block-detached:has([class*="img"]),
