  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* 2. 彻底隐藏前面的唱片图标 */
.msg-reply-block-detached:has(img)::before,
.msg-reply-block-detached:has(picture)::before,
.msg-reply-block-detached:has(.msg-reply-detached-media)::before,
.msg-reply-block-detached:has([class*="image"])::before,
.msg-reply-block-detached:has([class*="img"])::before,
.msg-reply-block-detached:has([class*="sticker"])::before {
  display: none !important;
}

/* 3. 确保里面的图片正常原样显示，不被截断，且自适应圆角 */
.msg-reply-block-detached img,
.msg-reply-block-detached picture,
.msg-reply-detached-media {
